        by_id = {str(row.get('id') or ''): row for row in terms if isinstance(row, dict) and row.get('id')}
        added = 0
        for row in defaults:
            term_id = str(row.get('id') or '')
            if term_id and term_id not in by_id:
                by_id[term_id] = row
